 WITH "DVO_BASE1" AS 
	( -- This CTE retrieves the company information
		SELECT DISTINCT
			  "DVO_SRC1"."COMPANY_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC1"."COMPANY_BK" AS "COMPANY_BK"
			, "SAT_SRC1_1_4"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC1_1_4"."ACCOUNT_NAME" AS "ACCOUNT_NAME"
        FROM {{ source('eli_dv_bv', 'hub_company') }} "DVO_SRC1"
		JOIN {{ ref('sat_ssc_company_bvv_curr') }} "SAT_SRC1_1_4" ON  "DVO_SRC1"."COMPANY_HKEY" = "SAT_SRC1_1_4"."COMPANY_HKEY"
	)
	, "DVO_BASE3" AS
	(	 -- This CTE retrieves the contact information
		SELECT DISTINCT
			  "DVO_SRC3"."CONTACT_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC3"."CONTACT_BK" AS "CONTACT_BK"
			, "SAT_SRC3_1_3"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC3_1_3"."CONTACT_NAME" AS "CONTACT_NAME"
			, "SAT_SRC3_1_3"."CONTACT_EMAIL" AS "CONTACT_EMAIL"
			, "SAT_SRC3_1_3"."CONTACT_PHONE" AS "CONTACT_PHONE"
			, "SAT_SRC3_1_3"."CONTACT_TITLE" AS "CONTACT_TITLE"
			, "SAT_SRC3_1_3"."CONTACT_BH_ID" AS "CONTACT_BH_ID"
			, "SAT_SRC3_1_3"."CONTACT_LAST_NAME" AS "CONTACT_LAST_NAME"
			, "SAT_SRC3_1_3"."CONTACT_FIRST_NAME" AS "CONTACT_FIRST_NAME"
			, "SAT_SRC3_1_3"."MAIN_CITY" AS "MAIN_CITY"
			, "SAT_SRC3_1_3"."CONTACT_EMAIL_2" AS "CONTACT_EMAIL_2"
			, "SAT_SRC3_1_3"."MIDDLE_NAME" AS "MIDDLE_NAME"
			, "SAT_SRC3_1_3"."MAIN_STATE" AS "MAIN_STATE"
			, "SAT_SRC3_1_3"."MAILING_CITY" AS "MAILING_CITY"
			, "SAT_SRC3_1_3"."MOBILE_PHONE" AS "MOBILE_PHONE"
			, "SAT_SRC3_1_3"."MAIN_STREET" AS "MAIN_STREET"
			, "SAT_SRC3_1_3"."MAILING_STATE" AS "MAILING_STATE"
			, "SAT_SRC3_1_3"."MAIN_COUNTRY" AS "MAIN_COUNTRY"
			, "SAT_SRC3_1_3"."MAILING_STREET" AS "MAILING_STREET"
			, "SAT_SRC3_1_3"."MAILING_COUNTRY" AS "MAILING_COUNTRY"
			, "SAT_SRC3_1_3"."MAIN_STATE_CODE" AS "MAIN_STATE_CODE"
			, "SAT_SRC3_1_3"."LINKEDIN_URL" AS "LINKEDIN_URL"
			, "SAT_SRC3_1_3"."MAIN_POSTAL_CODE" AS "MAIN_POSTAL_CODE"
			, "SAT_SRC3_1_3"."CONTACT_NICKNAME" AS "CONTACT_NICKNAME"
			, "SAT_SRC3_1_3"."MAILING_STATE_CODE" AS "MAILING_STATE_CODE"
			, "SAT_SRC3_1_3"."CONTACT_STATUS" AS "CONTACT_STATUS"
			, "SAT_SRC3_1_3"."MAILING_POSTAL_CODE" AS "MAILING_POSTAL_CODE"
			, "SAT_SRC3_1_3"."QUALIFIED_BUYER" AS "QUALIFIED_BUYER"
			, "SAT_SRC3_1_3"."LINE_OF_BUSINESS" AS "LINE_OF_BUSINESS"
			, "SAT_SRC3_1_3"."CONTACT_ELI_LEGACY_SYSTEM_ID" AS "CONTACT_ELI_LEGACY_SYSTEM_ID"
			, "SAT_SRC3_1_3"."QUALIFIED_BUYER_SINCE" AS "QUALIFIED_BUYER_SINCE"
			, "SAT_SRC3_1_3"."CONSULTANTS_HIRED_PER_YEAR" AS "CONSULTANTS_HIRED_PER_YEAR"
			, "SAT_SRC3_1_3"."CURRENT_CONSULTANT_HEADCOUNT" AS "CURRENT_CONSULTANT_HEADCOUNT"
		FROM {{ source('eli_dv_bv', 'hub_contact') }} "DVO_SRC3"
		INNER JOIN {{ ref('sat_ssc_contact_bvv_curr') }} "SAT_SRC3_1_3" ON  "DVO_SRC3"."CONTACT_HKEY" = "SAT_SRC3_1_3"."CONTACT_HKEY"
	)
	, "DVO_BASE5" AS 
	( 	-- This CTE retrieves the user information
		SELECT DISTINCT
			  "DVO_SRC5"."USER_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC5"."USER_BK" AS "USER_BK"
			, "SAT_SRC5_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
			, "SAT_SRC5_1_1"."NAME" AS "NAME"
		FROM {{ source('eli_dv_bv', 'hub_user') }} "DVO_SRC5"
		INNER JOIN {{ ref('sat_ssc_user_bvv_curr') }} "SAT_SRC5_1_1" ON  "DVO_SRC5"."USER_HKEY" = "SAT_SRC5_1_1"."USER_HKEY"
		ORDER BY "DVO_SRC5"."USER_HKEY", "SAT_SRC5_1_1"."_AIRBYTE_EXTRACTED_AT"
	)
	, "DVO_BASE2" AS 
	( 	-- This CTE retrieves the company relationships for contacts
		-- It ensures that we only get the latest company for each contact
		SELECT DISTINCT
			  "DVO_SRC2"."CONTACT_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC2"."LNK_CONTACT_COMPANY_HKEY" AS "BASE_OBJECT_L_H_KEY"
			, "DVO_SRC2"."COMPANY_HKEY" AS "BASE_OBJECT_F_H_KEY"
			, ROW_NUMBER() OVER (
				PARTITION BY "DVO_SRC2"."CONTACT_HKEY" -- Partition by contact to get the latest company
				ORDER BY "SAT_SRC2_1_3"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
			) AS "RN"
			, "SAT_SRC2_1_3"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
		FROM {{ source('eli_dv_bv', 'lnk_contact_company') }} "DVO_SRC2"
		INNER JOIN {{ ref('lks_ssc_contact_company_bvv_curr') }} "SAT_SRC2_1_3" ON  "DVO_SRC2"."LNK_CONTACT_COMPANY_HKEY" = "SAT_SRC2_1_3"."LNK_CONTACT_COMPANY_HKEY"
	)
	, "DVO_BASE4" AS 
	( 	-- This CTE retrieves the user relationships for contacts
		-- It ensures that we only get the latest user for each contact
		SELECT DISTINCT
			  "DVO_SRC4"."CONTACT_HKEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_SRC4"."LNK_CONTACT_USER_HKEY" AS "BASE_OBJECT_L_H_KEY"
			, "DVO_SRC4"."USER_HKEY" AS "BASE_OBJECT_F_H_KEY"
			, ROW_NUMBER() OVER (
				PARTITION BY "DVO_SRC4"."CONTACT_HKEY" -- Partition by contact to get the latest user
				ORDER BY "SAT_SRC4_1_1"."_AIRBYTE_EXTRACTED_AT" DESC -- Order by snapshot timestamp to get the latest
			) AS "RN"
			, "SAT_SRC4_1_1"."_AIRBYTE_EXTRACTED_AT" AS "SNAPSHOT__TIMESTAMP"
		FROM {{ source('eli_dv_bv', 'lnk_contact_user') }} "DVO_SRC4"
		INNER JOIN {{ ref('lks_ssc_contact_user_bvv_curr') }} "SAT_SRC4_1_1" ON  "DVO_SRC4"."LNK_CONTACT_USER_HKEY" = "SAT_SRC4_1_1"."LNK_CONTACT_USER_HKEY"
	)
		SELECT DISTINCT
			UPPER(SHA2(
				UPPER(REPLACE(COALESCE(TRIM(DVO_BASE3.CONTACT_BK),'~'), '\#', '\\\#')) || '\#' ||
				UPPER(REPLACE(COALESCE(TRIM(TO_CHAR(DVO_BASE3.SNAPSHOT__TIMESTAMP, 'DD/MM/YYYY HH24:MI:SS')),'~'), '\#', '\\\#')) || '\#'
			)) AS DIM_CONTACT_HKEY
			, "DVO_BASE3"."BASE_OBJECT_H_KEY" AS "BASE_OBJECT_H_KEY"
			, "DVO_BASE2"."BASE_OBJECT_L_H_KEY" AS "CONTACT_COMPANY_BASE_OBJECT_L_H_KEY"
			, "DVO_BASE3"."CONTACT_BK" AS "CONTACT_BK"
			, "DVO_BASE3"."SNAPSHOT__TIMESTAMP" AS "SNAPSHOT__TIMESTAMP"
			, "DVO_BASE1"."ACCOUNT_NAME" AS "ACCOUNT_NAME"
			, "DVO_BASE3"."CONTACT_NAME" AS "CONTACT_NAME"
			, "DVO_BASE3"."CONTACT_EMAIL" AS "CONTACT_EMAIL"
			, "DVO_BASE3"."CONTACT_PHONE" AS "CONTACT_PHONE"
			, "DVO_BASE3"."CONTACT_TITLE" AS "CONTACT_TITLE"
			, "DVO_BASE3"."CONTACT_BH_ID" AS "CONTACT_BH_ID"
			, "DVO_BASE3"."CONTACT_LAST_NAME" AS "CONTACT_LAST_NAME"
			, "DVO_BASE3"."CONTACT_FIRST_NAME" AS "CONTACT_FIRST_NAME"
			, "DVO_BASE3"."MAIN_CITY" AS "MAIN_CITY"
			, "DVO_BASE3"."CONTACT_EMAIL_2" AS "CONTACT_EMAIL_2"
			, "DVO_BASE3"."MIDDLE_NAME" AS "MIDDLE_NAME"
			, "DVO_BASE3"."MAIN_STATE" AS "MAIN_STATE"
			, "DVO_BASE3"."MAILING_CITY" AS "MAILING_CITY"
			, "DVO_BASE3"."MOBILE_PHONE" AS "MOBILE_PHONE"
			, "DVO_BASE3"."MAIN_STREET" AS "MAIN_STREET"
			, "DVO_BASE3"."MAILING_STATE" AS "MAILING_STATE"
			, "DVO_BASE3"."MAIN_COUNTRY" AS "MAIN_COUNTRY"
			, "DVO_BASE3"."MAILING_STREET" AS "MAILING_STREET"
			, "DVO_BASE3"."MAILING_COUNTRY" AS "MAILING_COUNTRY"
			, "DVO_BASE3"."MAIN_STATE_CODE" AS "MAIN_STATE_CODE"
			, "DVO_BASE3"."LINKEDIN_URL" AS "LINKEDIN_URL"
			, "DVO_BASE3"."MAIN_POSTAL_CODE" AS "MAIN_POSTAL_CODE"
			, "DVO_BASE3"."CONTACT_NICKNAME" AS "CONTACT_NICKNAME"
			, "DVO_BASE3"."MAILING_STATE_CODE" AS "MAILING_STATE_CODE"
			, "DVO_BASE3"."CONTACT_STATUS" AS "CONTACT_STATUS"
			, "DVO_BASE3"."MAILING_POSTAL_CODE" AS "MAILING_POSTAL_CODE"
			, "DVO_BASE3"."QUALIFIED_BUYER" AS "QUALIFIED_BUYER"
			, "DVO_BASE3"."LINE_OF_BUSINESS" AS "LINE_OF_BUSINESS"
			, "DVO_BASE3"."CONTACT_ELI_LEGACY_SYSTEM_ID" AS "CONTACT_ELI_LEGACY_SYSTEM_ID"
			, "DVO_BASE3"."QUALIFIED_BUYER_SINCE" AS "QUALIFIED_BUYER_SINCE"
			, "DVO_BASE3"."CONSULTANTS_HIRED_PER_YEAR" AS "CONSULTANTS_HIRED_PER_YEAR"
			, "DVO_BASE3"."CURRENT_CONSULTANT_HEADCOUNT" AS "CURRENT_CONSULTANT_HEADCOUNT"
			, "DVO_BASE5"."NAME" AS "OWNER_NAME"
		FROM "DVO_BASE3" "DVO_BASE3" -- MAIN_HUB: HUB_CONTACT
		--Join HUB_CONTACT to link table on Primary key HKEY to get the company
		INNER JOIN "DVO_BASE2" "DVO_BASE2" ON  "DVO_BASE3"."BASE_OBJECT_H_KEY" = "DVO_BASE2"."BASE_OBJECT_H_KEY" 
			AND "DVO_BASE2"."RN" = 1 -- Get the latest company for the contact
		--Join HUB_COMPANY to link table on Foreign key HKEY
		INNER JOIN "DVO_BASE1" "DVO_BASE1" ON  "DVO_BASE2"."BASE_OBJECT_F_H_KEY" = "DVO_BASE1"."BASE_OBJECT_H_KEY"
		--Join HUB_CONTACT to link table on Primary key HKEY to get the user
		INNER JOIN "DVO_BASE4" "DVO_BASE4" ON  "DVO_BASE3"."BASE_OBJECT_H_KEY" = "DVO_BASE4"."BASE_OBJECT_H_KEY" 
			AND "DVO_BASE4"."RN" = 1 -- Get the latest user for the contact
		--Join HUB_USER to link table on Foreign key HKEY
		INNER JOIN "DVO_BASE5" "DVO_BASE5" ON  "DVO_BASE4"."BASE_OBJECT_F_H_KEY" = "DVO_BASE5"."BASE_OBJECT_H_KEY"